from collections import Counter


def smallest_window(log: list[str], codes: list[str]) -> tuple[int, int] | None:
    if not codes:
        return None
    need = Counter(codes)
    missing = len(codes)
    have: Counter[str] = Counter()
    best: tuple[int, int] | None = None
    left = 0
    for right, code in enumerate(log):
        if code in need:
            have[code] += 1
            if have[code] <= need[code]:
                missing -= 1
        while missing == 0:
            if best is None or right - left < best[1] - best[0]:
                best = (left, right)
            out = log[left]
            if out in need:
                have[out] -= 1
                if have[out] < need[out]:
                    missing += 1
            left += 1
    return best
